#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define VOCAB_SIZE 50257
#define N_LAYER 12
#define N_HEAD 12
#define N_EMBD 768
#define N_CTX 1024

float *read_floats(FILE *f, int n) {
    float *buf = malloc(n * sizeof(float));
    if (fread(buf, sizeof(float), n, f) != n) {
        fprintf(stderr, "Failed to read\n");
        exit(1);
    }
    return buf;
}

void softmax(float *x, int n) {
    float max_val = x[0];
    for (int i = 1; i < n; i++) if (x[i] > max_val) max_val = x[i];
    float sum = 0;
    for (int i = 0; i < n; i++) {
        x[i] = exp(x[i] - max_val);
        sum += x[i];
    }
    for (int i = 0; i < n; i++) x[i] /= sum;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <ckpt> <vocab> <prompt>\n", argv[0]);
        return 1;
    }

    FILE *ckpt = fopen(argv[1], "rb");
    FILE *vocab_f = fopen(argv[2], "rb");
    if (!ckpt || !vocab_f) {
        fprintf(stderr, "Failed to open files\n");
        return 1;
    }

    // Load vocabulary
    char **vocab = malloc(VOCAB_SIZE * sizeof(char*));
    char line[256];
    int vcnt = 0;
    while (fgets(line, sizeof(line), vocab_f) && vcnt < VOCAB_SIZE) {
        line[strcspn(line, "\n")] = 0;
        vocab[vcnt] = malloc(strlen(line) + 1);
        strcpy(vocab[vcnt], line);
        vcnt++;
    }
    fclose(vocab_f);

    // Load embeddings from checkpoint
    float *wte = read_floats(ckpt, VOCAB_SIZE * N_EMBD);
    float *wpe = read_floats(ckpt, N_CTX * N_EMBD);

    // Skip layer weights, just use embeddings for now
    // For each layer: ln_1/w, ln_1/b, c_attn/w, c_attn/b, c_proj/w, c_proj/b, 
    //                 ln_2/w, ln_2/b, c_fc/w, c_fc/b, c_proj2/w, c_proj2/b
    for (int l = 0; l < N_LAYER; l++) {
        float *tmp;
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // ln_1/w
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // ln_1/b
        tmp = read_floats(ckpt, 3*N_EMBD*N_EMBD); free(tmp);  // c_attn/w
        tmp = read_floats(ckpt, 3*N_EMBD); free(tmp);         // c_attn/b
        tmp = read_floats(ckpt, N_EMBD*N_EMBD); free(tmp);    // c_proj/w
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // c_proj/b
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // ln_2/w
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // ln_2/b
        tmp = read_floats(ckpt, 4*N_EMBD*N_EMBD); free(tmp);  // c_fc/w
        tmp = read_floats(ckpt, 4*N_EMBD); free(tmp);         // c_fc/b
        tmp = read_floats(ckpt, N_EMBD*4*N_EMBD); free(tmp);  // c_proj2/w
        tmp = read_floats(ckpt, N_EMBD); free(tmp);           // c_proj2/b
    }

    float *lnfw = read_floats(ckpt, N_EMBD);
    float *lnfb = read_floats(ckpt, N_EMBD);

    // Tokenize input (simple: take first char as token if < 256)
    int tokens[100];
    int n_tokens = 0;
    for (int i = 0; argv[3][i] && n_tokens < 100; i++) {
        unsigned char c = argv[3][i];
        tokens[n_tokens++] = c;
    }

    // Simple generation: use embedding sum for logits
    float x[N_EMBD] = {0};
    for (int i = 0; i < n_tokens; i++) {
        int tok = tokens[i];
        for (int j = 0; j < N_EMBD; j++) {
            x[j] += wte[tok * N_EMBD + j] + wpe[i * N_EMBD + j];
        }
    }

    // Generate 20 tokens
    for (int gen = 0; gen < 20; gen++) {
        float logits[VOCAB_SIZE];
        for (int v = 0; v < VOCAB_SIZE; v++) {
            logits[v] = 0;
            for (int j = 0; j < N_EMBD; j++) {
                logits[v] += x[j] * wte[v * N_EMBD + j];
            }
        }

        // Argmax
        int best = 0;
        float best_val = logits[0];
        for (int v = 1; v < VOCAB_SIZE; v++) {
            if (logits[v] > best_val) {
                best_val = logits[v];
                best = v;
            }
        }

        printf("%s", vocab[best]);
        fflush(stdout);

        // Update x with new token embedding
        for (int j = 0; j < N_EMBD; j++) {
            x[j] = x[j] * 0.9 + wte[best * N_EMBD + j] * 0.1;
        }
    }

    printf("\n");
    fclose(ckpt);
    for (int i = 0; i < vcnt; i++) free(vocab[i]);
    free(vocab);
    return 0;
}
